const POOL = [{"id": "GRAPH-1", "lens": "GRAPH", "tier": "high", "verdict": "CONFIRMED", "title_idea": "The Whisperer Who Retreats: Shaytan's Name in the Last Surah Is a Vanishing-Star Word", "claim": "The root خنس (to shrink back, retreat) appears in exactly 2 verses of the Quran: 81:15, where al-khunnas are the retreating celestial bodies Allah swears by (paired with 'al-jawar al-kunnas' in 81:16), and 114:4, where al-khannas is the whisperer who retreats. Scope: ROOT field of the morphological corpus; 2 tokens, 2 verses.", "evidence": "ROOT:خنس census = 2 tokens / 2 verses: 81:15 خُنَّسِ (N, LEM:خُنَّس) and 114:4 خَنَّاسِ (N, LEM:خَنّاس, ADJ). 81:15-16 context: 'fa-la uqsimu bil-khunnas, al-jawari al-kunnas'; 114:4: 'min sharri al-waswas al-khannas'.", "refs": ["81:15", "114:4"], "overlap_note": "Nearest: /posts/weapons-against-waswasa and /posts/footsteps-of-shaytan (shaytan tactics). Neither touches the khunnas/khannas root link. None ships this reveal.", "angle": "The Quran's final surah names shaytan with the same rare root it uses for stars that vanish when dawn comes — the whisperer disappears the way stars do when light shows up, and dhikr is the dawn."}, {"id": "GRAPH-2", "lens": "GRAPH", "tier": "high", "verdict": "CONFIRMED", "title_idea": "Recite It Slowly: The Command Allah Describes Himself Doing First", "claim": "The root رتل occurs in exactly 2 verses of the Quran, and they mirror each other: 25:32 'rattalnahu tartilan' — Allah describing His own delivery of the Quran — and 73:4 'rattil al-Qur'ana tartilan' — the command to the Prophet to recite it slowly. Both use the identical Form II verb (LEM:رَتَّلْ) plus the identical verbal noun tartil (LEM:تَرْتِيل). Scope: ROOT field; 4 tokens, 2 verses. Ordering claim is mushaf-position only, no chronology asserted.", "evidence": "ROOT:رتل census = 4 tokens / 2 verses: 25:32 رَتَّلْ (PERF|VF:2|1P) + تَرْتِيلًا (VN), 73:4 رَتِّلِ (IMPV|VF:2|2MS) + تَرْتِيلًا (VN). 25:32 text: 'kadhalika linuthabbita bihi fu'adaka wa-rattalnahu tartila'; 73:4: 'wa-rattil al-qur'ana tartila'.", "refs": ["25:32", "73:4"], "overlap_note": "none — no published article on tartil or recitation pace.", "angle": "Whatever tajwid class told you to slow down, the Quran itself only uses this word twice: once as a command to you, once as Allah saying He did it that way first — slow recitation is imitation of the divine delivery."}, {"id": "GRAPH-3", "lens": "GRAPH", "tier": "high", "verdict": "CONFIRMED", "title_idea": "Borrowed Fire, Borrowed Light: The Word From Musa's Night That Comes Back on Judgment Day", "claim": "The root قبس (a borrowed flame; to borrow fire/light) occurs in exactly 3 verses: 20:10 and 27:7, where Musa tells his family he hopes to bring them a qabas from the fire he sees, and 57:13, where the hypocrites on Judgment Day beg the believers 'let us borrow (naqtabis) from your light' — and are refused with a wall struck between them. Scope: ROOT field; 3 tokens, 3 verses.", "evidence": "ROOT:قبس census = 3 tokens / 3 verses: 20:10 قَبَسٍ (N), 27:7 قَبَسٍ (N, 'bi-shihabin qabas'), 57:13 نَقْتَبِسْ (V, IMPF|VF:8). 57:13 context verified: hypocrites ask 'unzuruna naqtabis min nurikum', answer 'irji'u wara'akum fa-l-tamisu nura', then 'fa-duriba baynahum bi-surin lahu bab'.", "refs": ["20:10", "27:7", "57:13"], "overlap_note": "NEAR: /posts/musa-fire-three-tellings-quran ('The Night Musa Went to Borrow a Flame') owns the Musa-fire narrative and the borrow framing. This differs: the reveal is the root's third and final occurrence — the only other people in the Quran who ask to borrow light are the hypocrites at the wall, and they are turned away. Position as a sequel: the word's whole arc is Musa asked and got prophethood; they ask and get a door slammed.", "angle": "The man who went to borrow a flame walked back with revelation; the people who ask to borrow light on the Last Day get a wall — same rare word, opposite endings, and the difference was when you asked."}, {"id": "GRAPH-4", "lens": "GRAPH", "tier": "high", "verdict": "CONFIRMED", "title_idea": "You Are the Deposit: The Quran's Pawn Word Appears Three Times", "claim": "The root رهن (pledge/collateral) occurs in exactly 3 verses: 2:283, the debt-law verse where goods are handed over as security (rihan maqbudah); 52:21, 'every person is held in pledge (rahin) for what he earned'; and 74:38, 'every soul is held in pledge (rahinah) for what it earned.' Its one commercial use has goods as the deposit; its two hereafter uses make the person the deposit. Scope: ROOT field; 3 tokens, 3 verses.", "evidence": "ROOT:رهن census = 3 tokens / 3 verses: 2:283 رِهَٰنٌ (LEM:رِهان, MP), 52:21 رَهِينٌ (LEM:رَهِين), 74:38 رَهِينَةٌ (LEM:رَهِينَة). Texts verified: 2:283 'fa-rihanun maqbudah' in the no-scribe-while-traveling clause; 52:21 'kullu imri'in bima kasaba rahin'; 74:38 'kullu nafsin bima kasabat rahinah'.", "refs": ["2:283", "52:21", "74:38"], "overlap_note": "none — no published article touches rahn/collateral.", "angle": "In the Quran's one verse about collateral you hand over your goods until the debt clears; in the other two uses of the same word, the thing sitting in the vault is you — held against a debt only your own deeds can redeem."}, {"id": "GRAPH-5", "lens": "GRAPH", "tier": "high", "verdict": "CONFIRMED", "title_idea": "The Word for Swallowing What You Feel: All Six Times the Quran Uses It", "claim": "The root كظم (to choke back, suppress) occurs in exactly 6 verses: 3:134 (those who swallow their anger — praised, al-kazimin al-ghayz), 12:84 (Ya'qub, kazim with grief over Yusuf), 16:58 and 43:17 (the man told his newborn is a girl — 'his face darkens and he is kazim' — an identical 5-word sentence in both verses), 40:18 (Judgment Day: hearts at the throats, kazimin), and 68:48 (Yunus, makzum inside the fish). Scope: ROOT field; 6 tokens, 6 verses. The 16:58/43:17 repetition is an exact textSimple substring match found in exactly those 2 verses.", "evidence": "ROOT:كظم census = 6 tokens / 6 verses: 3:134 كَٰظِمِينَ, 12:84 كَظِيمٌ, 16:58 كَظِيمٌ, 40:18 كَٰظِمِينَ, 43:17 كَظِيمٌ, 68:48 مَكْظُومٌ. Substring 'ظل وجهه مسودا وهو كظيم' matches exactly 2 verses: 16:58, 43:17.", "refs": ["3:134", "12:84", "16:58", "40:18", "43:17", "68:48"], "overlap_note": "NEAR: /posts/the-father-who-waited-yaqub-and-the-grief-that-became-blindness and /posts/sabr-jamil cover Ya'qub's grief (one of the six). This differs: it is a full census of one bodily word — praised in one verse, embodied by a prophet in two, and diagnosed in the daughter-news idolater in two — showing the Quran distinguishes swallowing anger (praised) from swallowing shame (condemned context) with the same muscle.", "angle": "The Quran has one word for choking your feelings down, and its six uses split cleanly: swallow your anger and you're praised; swallow your grief and you're Ya'qub; swallow your shame at a daughter and you're the verse's villain — same throat, different verdicts."}, {"id": "GRAPH-6", "lens": "GRAPH", "tier": "high", "verdict": "CONFIRMED", "title_idea": "Hearts in Throats: The Quran Uses This Image Exactly Twice", "claim": "The word hanajir (throats, root حنجر) occurs in exactly 2 verses: 33:10, describing the believers at the siege of the Trench ('when hearts reached the throats'), and 40:18, describing everyone on the approaching Day ('hearts at the throats, choking'). Scope: ROOT field; 2 tokens, 2 verses; substring 'الحناجر' also matches exactly these 2 verses.", "evidence": "ROOT:حنجر census = 2 tokens / 2 verses: 33:10 حَنَاجِرَ, 40:18 حَنَاجِرِ. textSimple substring 'الحناجر' -> ['33:10','40:18']. Bonus corpus fact: 40:18 also carries كَٰظِمِينَ (root كظم), linking it to the swallowed-feelings census.", "refs": ["33:10", "40:18"], "overlap_note": "none — no published article on the hanajir pair or the Trench/Judgment mirror.", "angle": "The Quran's most physical image of fear appears twice: once on the believers' worst day in this world — a day they survived — and once on the Day everyone meets; the first time is given to you as a rehearsal you can actually study."}, {"id": "GRAPH-7", "lens": "GRAPH", "tier": "high", "verdict": "CONFIRMED", "title_idea": "Barzakh: The Word for Where the Dead Wait Is an Ocean Word", "claim": "Barzakh occurs exactly 3 times in the Quran, and two of the three are about seawater: 25:53 and 55:20 describe the unseen barrier that keeps two seas — sweet and salt — from mixing as they meet; 23:100 names the barrier behind the dead 'until the Day they are raised.' Scope: ROOT field (root برزخ); 3 tokens, 3 verses.", "evidence": "ROOT:برزخ census = 3 tokens / 3 verses: 23:100 بَرْزَخٌ, 25:53 بَرْزَخًا, 55:20 بَرْزَخٌ. Contexts verified: 25:53 'maraja al-bahrayni... wa-ja'ala baynahuma barzakhan'; 55:20 'baynahuma barzakhun la yabghiyan'; 23:100 'wa-min wara'ihim barzakhun ila yawmi yub'athun'.", "refs": ["23:100", "25:53", "55:20"], "overlap_note": "none — no published article on barzakh; the enclosed-spaces article (/posts/quran-enclosed-spaces-well-cave-whale-fire) is about narrative spaces, not this word.", "angle": "Before the Quran uses 'barzakh' for the wait between death and resurrection, it points at it twice in nature — the invisible wall where two seas touch and never mix — so the word for your own waiting room is something you can go stand on a shore and watch working."}, {"id": "GRAPH-8", "lens": "GRAPH", "tier": "high", "verdict": "CONFIRMED", "title_idea": "The Greed You're Born Holding — and the Sentence the Quran Repeats Word for Word About It", "claim": "The root شحح (shuhh, clinging greed of the soul) occurs in exactly 4 verses: 4:128 ('souls are made ever-present with shuhh' — it is the default state), 33:19 (the hypocrites, ashihhah, twice in the one verse), and 59:9 and 64:16, which both end with the identical sentence 'wa man yuqa shuhha nafsihi fa-ula'ika hum al-muflihun' — 'whoever is protected from the shuhh of his own soul, those are the successful.' The verb yuqa is passive: protection is received, not achieved. Scope: ROOT field, 5 tokens / 4 verses; the repeated sentence is an exact textSimple substring found in exactly those 2 verses.", "evidence": "ROOT:شحح census = 5 tokens / 4 verses: 4:128 شُّحَّ, 33:19 أَشِحَّةً ×2, 59:9 شُحَّ, 64:16 شُحَّ. Substring 'ومن يوق شح نفسه فاولايك هم المفلحون' -> exactly ['59:9','64:16']. 4:128 context: 'wa-uhdirat al-anfusu al-shuhh'.", "refs": ["4:128", "33:19", "59:9", "64:16"], "overlap_note": "none — bukhl/stinginess root has no published article either; nearest is the infaq material inside taqwa/rizq articles, which never treats shuhh.", "angle": "One verse says this greed comes pre-installed in every soul, and the Quran's twice-repeated verdict sentence uses a passive verb — you don't beat your greed, you get shielded from it, which changes what you ask for."}, {"id": "GRAPH-9", "lens": "GRAPH", "tier": "high", "verdict": "CONFIRMED", "title_idea": "Shaken: The Quran's Earthquake Verb Hits Believers Twice and the Earth Once", "claim": "The verb from root زلزل (to quake) occurs 3 times in the Quran, always passive: 99:1, where the earth is shaken (zulzilat), and 2:214 and 33:11, where it is the believers who are shaken (zulzilu) — in 2:214 shaken until the Messenger himself says 'when is Allah's help coming?', and in 33:11 at the Trench, 'shaken with a severe shaking.' Counting the noun too, the root appears in exactly 4 verses (add 22:1, the zalzalah of the Hour). Scope: ROOT field, verb vs noun split stated explicitly; 6 tokens, 4 verses.", "evidence": "ROOT:زلزل census = 6 tokens / 4 verses: verbs (all PERF|PASS): 2:214 زُلْزِلُ (3MP), 33:11 زُلْزِلُ (3MP), 99:1 زُلْزِلَتِ (3FS); nouns: 22:1 زَلْزَلَةَ, 33:11 زِلْزَالًا, 99:1 زِلْزَالَ. Contexts verified: 2:214 'wa-zulzilu hatta yaqula al-rasul... mata nasru Allah'; 33:11 'hunalika ubtuliya al-mu'minuna wa-zulzilu zilzalan shadida'.", "refs": ["2:214", "22:1", "33:11", "99:1"], "overlap_note": "none — /posts/al-qiyamah-mountains-move is about mountains on the Day, not the zalzala verb applied to believers.", "angle": "Everyone knows Surah Az-Zalzalah, where the ground shakes — but the Quran uses that exact verb on people twice and on the planet once, and one of the people-verses says the shaking got bad enough that a prophet asked where God's help was; being shaken is written into the believer's job description, not a sign you failed it."}, {"id": "GRAPH-10", "lens": "GRAPH", "tier": "high", "verdict": "CONFIRMED", "title_idea": "The Mustard Seed Appears Twice: Once on God's Scales, Once in a Father's Advice", "claim": "Khardal (mustard seed) occurs in exactly 2 verses, inside the identical phrase 'mithqala habbatin min khardal' (the weight of a mustard seed): 21:47, describing the scales of the Day of Judgment that miss nothing of that weight, and 31:16, where Luqman tells his son that a deed of that weight — hidden in a rock, in the heavens, or in the earth — Allah will bring out. Scope: ROOT field for the count; exact textSimple substring for the shared phrase (2 verses).", "evidence": "ROOT:خردل census = 2 tokens / 2 verses: 21:47, 31:16. Substring 'مثقال حبة من خردل' -> exactly ['21:47','31:16']. 21:47 is the mawazin (scales) verse; 31:16 opens 'ya bunayya' (O my dear son).", "refs": ["21:47", "31:16"], "overlap_note": "NEAR: /posts/mizan-weighing-day-of-judgment covers the scales generally. This differs: the reveal is the two-occurrence exactness and the register split — the courtroom's unit of measure is taught the other time by a father to his boy, gently, before the courtroom ever convenes.", "angle": "The unit of measure the Last Day's scales will use appears exactly one other time in the Quran — in a father's quiet advice to his son — which means the syllabus for the final exam was handed out at home."}, {"id": "GRAPH-11", "lens": "GRAPH", "tier": "high", "verdict": "CONFIRMED", "title_idea": "Maqt: The Disgust Word the Quran Uses in Five Verses — Once for How the Damned Feel About Themselves", "claim": "The root مقت (loathing, abhorrence) occurs in exactly 5 verses (6 tokens): 4:22 (marrying your father's former wife 'was a fahishah and maqt'), 35:39 (disbelief increases its people only in maqt before their Lord), 40:35 (those who argue against Allah's signs without warrant — 'great is the maqt'), 61:3 ('great is the maqt with Allah that you say what you do not do'), and 40:10, the only verse with the word twice: 'Allah's maqt of you is greater than your maqt of yourselves' — addressed to the damned, presupposing they already loathe themselves. Scope: ROOT field.", "evidence": "ROOT:مقت census = 6 tokens / 5 verses: 4:22, 35:39, 40:10 (مَقْتُ + مَّقْتِ), 40:35, 61:3. 40:10 text verified: 'la-maqtu Allahi akbaru min maqtikum anfusakum idh tud'awna ila al-imani fa-takfurun'. 61:3 verified: 'kabura maqtan inda Allahi an taqulu ma la taf'alun'.", "refs": ["4:22", "35:39", "40:10", "40:35", "61:3"], "overlap_note": "none — no published article on maqt.", "angle": "Make the short list of what actually triggers the Quran's word for divine disgust and one entry stops you cold: saying what you don't do sits on the same five-verse list as incest-adjacent marriage and outright disbelief — and the list's only doubled use says the damned will hate themselves before they learn God's hatred was greater."}, {"id": "GRAPH-12", "lens": "GRAPH", "tier": "high", "verdict": "CONFIRMED", "title_idea": "Sarsar: The Wind Word the Quran Reserves for Exactly One People", "claim": "Sarsar (a furious, shrieking wind, root صرصر) occurs in exactly 3 verses — 41:16, 54:19, 69:6 — and in all three it describes the wind sent on the people of 'Ad and no one else (context verified: 41:15 names 'Ad, 54:18 names 'Ad, 69:6 opens 'wa-amma 'Adun'). The two-word phrase 'rihan sarsaran' repeats verbatim in 41:16 and 54:19. Scope: ROOT field for the count; textSimple for the contexts and phrase.", "evidence": "ROOT:صرصر census = 3 tokens / 3 verses: 41:16 صَرْصَرًا, 54:19 صَرْصَرًا, 69:6 صَرْصَرٍ. Substring 'ريحا صرصرا' -> exactly ['41:16','54:19']. 'Ad attribution verified in 41:15, 54:18, 69:4-6 textSimple.", "refs": ["41:16", "54:19", "69:6"], "overlap_note": "NEAR: /posts/hud-and-ad-when-the-wind-became-the-message tells the 'Ad wind story. This differs: the reveal is corpus-exclusivity of the word itself — a vocabulary item locked to one nation across three surahs — which the narrative article does not claim. If the braintrust judges the overlap too close, drop this one first; the other 11 are clean.", "angle": "The Quran keeps a special word for wind that it spends on exactly one nation — the people who bragged 'who is stronger than us?' got a wind with its own name, used three times and never lent to anyone else."}, {"id": "BRACKET-1", "lens": "BRACKET", "tier": "high", "verdict": "CONFIRMED", "title_idea": "The Quran's First Word About Blessing Is a Prayer for It. Its Last Is a Question About It.", "claim": "In mushaf order, the root نعم (140 tagged segments; covers anʿama/niʿmah/naʿīm and also anʿām 'livestock') first occurs at 1:7 — the Fatiha's 'the path of those You have blessed' (anʿamta) — and last occurs at 102:8 — 'then you will surely be asked, that Day, about the blessings' (al-naʿīm). Blessing enters the Quran as something you ask to be given and exits as something you will be asked about. Both bookend surahs are Meccan by standard classification.", "evidence": "root نعم n=140 segments; first=1:7 (أنعمت, 'صراط الذين انعمت عليهم'), last=102:8 (النعيم, 'ثم لتسالن يوميذ عن النعيم'); tail check confirms nothing after 102:8 (prior three: 89:15, 92:19, 93:11). Lemma breakdown of the root: أنعم 17, نعمة 50, نِعْمَ 18, نَعَم/أنعام 33, نعيم 17, نعماء 1, نعمة(alt) 2, ناعمة 1, نعّم 1.", "refs": ["1:7", "102:8"], "overlap_note": "an-nasr-final-words-corpus-quran shares the 'word retires meaningfully' flavor but is about surah 110's vocabulary; no published article on niʿmah/naʿīm or on 102:8. Disclose in-article that the root also covers anʿām (livestock — itself named as blessing).", "angle": "Every du'a you make for blessing sits between these two verses: the opening prayer to receive it and the closing notice that you'll answer for it."}, {"id": "BRACKET-2", "lens": "BRACKET", "tier": "high", "verdict": "CONFIRMED", "title_idea": "The Quran's First 'Forever' Is Paradise. Its Last Is a Man Who Thinks Money Bought It.", "claim": "In mushaf order, the root خلد (to last forever; 87 tagged segments) first occurs at 2:25 — believers 'abiding forever' (khalidun) in gardens — and last occurs at 104:3 — the wealth-hoarder who 'thinks his money has made him immortal' (akhladahu). Real eternity opens the root's story; counterfeit, purchasable eternity closes it. First is Medinan (al-Baqarah), last is Meccan (al-Humazah) — this is mushaf order, not order of revelation.", "evidence": "root خلد n=87; first=2:25 (خالدون), last=104:3 (أخلده, 'يحسب ان ماله اخلده'); tail: 76:19, 98:6, 98:8, then 104:3 — nothing after.", "refs": ["2:25", "104:3"], "overlap_note": "No published article on khulud/akhlada; the-weight-of-keys covers Qarun's wealth but not this root or 104:3.", "angle": "The same word carries the thing everyone wants (living forever) from the only place it's real to the place everyone actually shops for it."}, {"id": "BRACKET-3", "lens": "BRACKET", "tier": "high", "verdict": "CONFIRMED", "title_idea": "The Quran's First Disease and Its Last Are the Same Disease — and It's Not in the Body", "claim": "In mushaf order, the root مرض (sickness; 24 tagged segments) first occurs at 2:10 and last occurs at 74:31 — and both bookends sit inside the identical three-word phrase 'في قلوبهم مرض' ('in their hearts is a disease'), an exact textSimple phrase that occurs 11 times in the Quran with 2:10 as its first and 74:31 as its last. In between, the root mostly means ordinary bodily illness (travel and prayer concessions for 'the sick'). First is Medinan (al-Baqarah); last is in Meccan al-Muddaththir (74:31 is a verse some classical lists flag as later — disclose in-article).", "evidence": "root مرض n=24; first=2:10, last=74:31; phrase 'في قلوبهم مرض' count=11 in textSimple, first hit 2:10, last hit 74:31; substring confirmed present in 74:31.", "refs": ["2:10", "74:31"], "overlap_note": "qalb-sealed-rusted-heart-quran is the template sibling (first/last of قلب). Different root, different mechanic: qalb's bookends reverse agency; marad's bookends are the same unchanged diagnosis. Position as a companion piece, and say so.", "angle": "The word for sickness enters the Quran attached to the heart, spends the middle of the book excusing sick bodies from fasting and fighting, then exits attached to the heart again — the body's illness gets concessions, the heart's gets a bracket."}, {"id": "BRACKET-4", "lens": "BRACKET", "tier": "high", "verdict": "CONFIRMED", "title_idea": "The First Refuge Anyone Seeks in the Quran Isn't From the Devil", "claim": "In mushaf order, the root عوذ (seeking refuge; 17 tagged segments) first occurs at 2:67, where Musa says 'aʿudhu billah' — seeking refuge from 'being among the ignorant' (i.e., from mocking people). Its final two occurrences are the opening words of the mushaf's last two surahs (113:1, 114:1), and the very last is 114:1 'qul aʿudhu bi-rabbi-n-nas.' The first and last occurrence are the identical surface word أعوذ. First is Medinan (al-Baqarah); the classification of 113–114 is disputed (Meccan by majority). Mushaf order, not chronology.", "evidence": "root عوذ n=17; first=2:67 (أعوذ, Musa: 'اعوذ بالله ان اكون من الجاهلين'), last=114:1 (أعوذ); tail: 44:20, 72:6, 113:1, 114:1 — the final two occurrences open the final two surahs.", "refs": ["2:67", "113:1", "114:1"], "overlap_note": "weapons-against-waswasa presumably cites the muʿawwidhatayn as a tool; no published piece on the first istiʿadhah being Musa's refuge from mockery, or on the aʿudhu bracket across the whole mushaf.", "angle": "Everyone knows the Quran ends in 'I seek refuge.' Almost no one knows the first person to say it in the book was fleeing sarcasm, not Shaytan — the first thing a prophet refuses to be is a mocker."}, {"id": "BRACKET-5", "lens": "BRACKET", "tier": "high", "verdict": "CONFIRMED", "title_idea": "'We Raised It Over You' vs 'We Raised It For You': One Verb, Two Prepositions, the Whole Difference", "claim": "In mushaf order, the root رفع (to raise; 29 tagged segments) first occurs at 2:63 — 'wa-rafaʿna fawqakum al-Tur' (We raised the Mount OVER you, a warning hanging above covenant-breakers) — and last occurs at 94:4 — 'wa-rafaʿna laka dhikrak' (We raised FOR you your renown, a gift to the Prophet). Both bookends are the identical divine first-person-plural perfect verb رفعنا; only the preposition changes: fawqa (over) vs laka (for). First is Medinan, last is Meccan ash-Sharh — mushaf order, not chronology.", "evidence": "root رفع n=29; first=2:63 (رفعنا فوقكم الطور), last=94:4 (رفعنا لك ذكرك); tail: 80:14, 88:13, 88:18, 94:4. Both first and last segments have surface word رَفَعْ + نَا (rafaʿna).", "refs": ["2:63", "94:4"], "overlap_note": "budge-root-voice-flip-death uses a voice flip (passive/active); this is a different mechanic (same active verb, preposition flip). No published rafa'a article.", "angle": "The same divine 'We raised' that once held a mountain over a nation's head ends the Quran's story holding a man's name up — the distance between fear and honor is one preposition."}, {"id": "BRACKET-6", "lens": "BRACKET", "tier": "high", "verdict": "CONFIRMED", "title_idea": "The Quran Describes Deluded People for 79 Surahs. Then It Turns and Asks If You're One.", "claim": "In mushaf order, the root غرر (to delude/deceive; 27 tagged segments) first occurs at 3:24 — 'their forgeries deluded THEM in their religion' (gharrahum, third person, about other people) — and last occurs at 82:6 — 'O human, what deluded YOU about your Generous Lord?' (gharraka, second person, direct address to the reader). Both bookends are the same bare perfect verb غرّ; the only change is the pronoun: from them to you, from description to interrogation. First is Medinan (Aal Imran), last is Meccan (al-Infitar) — mushaf order, not chronology.", "evidence": "root غرر n=27; first=3:24 (غرهم, 'وغرهم في دينهم ما كانوا يفترون'), last=82:6 (غرك, 'يا ايها الانسان ما غرك بربك الكريم'); tail: 57:14, 57:20, 67:20, 82:6.", "refs": ["3:24", "82:6"], "overlap_note": "none — no published article on ghurur/82:6.", "angle": "Every earlier verse with this word lets you watch deluded people from a safe distance; the word's final appearance closes the distance and points at you."}, {"id": "BRACKET-7", "lens": "BRACKET", "tier": "high", "verdict": "CONFIRMED", "title_idea": "Laughing and Crying Enter the Quran in the Same Verse. Only One Gets the Last Word.", "claim": "In mushaf order, the roots ضحك (laugh; 10 tagged segments) and بكي (weep; 7 tagged segments) BOTH make their first appearance in the same verse, 9:82 ('so let them laugh a little and weep much'). Weeping's last occurrence is 53:60 — 'you laugh and you do not weep' — after which tears never appear again. Laughter continues for thirty more surahs and exits at 83:34: 'so Today, those who believed are laughing at the disbelievers' — the direct reversal of 83:29, where the criminals used to laugh at the believers. First bookend is Medinan (at-Tawbah), last is Meccan (al-Mutaffifin) — mushaf order, not chronology.", "evidence": "root ضحك all refs (n=10): 9:82, 11:71, 23:110, 27:19, 43:47, 53:43, 53:60, 80:39, 83:29, 83:34. root بكي all refs (n=7): 9:82, 12:16, 17:109, 19:58, 44:29, 53:43, 53:60. Shared first ref: 9:82. Weep-last=53:60; laugh-last=83:34.", "refs": ["9:82", "53:60", "83:29", "83:34"], "overlap_note": "none — no published laughter/weeping article.", "angle": "'Who laughs last' is literally answerable in the Quran, by count: tears run out at 53:60, and the book's final laugh belongs to the believers who were being laughed at."}, {"id": "BRACKET-8", "lens": "BRACKET", "tier": "high", "verdict": "CORRECTED", "title_idea": "The Quran Mentions a Shirt Exactly Six Times. All Six Are the Same Shirt.", "claim": "The root قمص (shirt) occurs exactly 6 times in the Quran, all six inside Surah Yusuf (12:18,25,26,27,28,93). It is one of only THREE roots of frequency 5-100 whose first and last occurrence fall in the same surah — the other two being صيد (game/hunting, all 5 occurrences in al-Ma'idah) and كهف (cave, all 6 in al-Kahf). [Miner's original 'five roots' is wrong — verified count is three.] First appearance: the shirt smeared with false blood (12:18); last: the shirt cast over Ya'qub's face that restores his sight (12:93). Same garment: instrument of the lie, the verdict, and the healing.", "evidence": "root قمص n=6, refs: 12:18, 12:25, 12:26, 12:27, 12:28, 12:93 — no occurrence outside surah 12. Same-surah bracket sweep over 721 roots (freq 5–100) yields exactly 5 such roots: شطر, ميل, صيد, قمص, كهف.", "refs": ["12:18", "12:25", "12:26", "12:27", "12:28", "12:93"], "overlap_note": "Several Yusuf articles are published (the well, the women of Egypt, la-tathrib, prison) but none on the shirt. Distinct object-level reveal.", "angle": "The same piece of cloth that carried the lie that blinded a father carries the truth that heals him — and the Quran never lets the word leave that one story."}, {"id": "BRACKET-9", "lens": "BRACKET", "tier": "high", "verdict": "CONFIRMED", "title_idea": "The First 'Salam' in the Quran Gets Rejected. The Last One Can't Be.", "claim": "In mushaf order, the lemma سَلام (the noun 'peace,' 42 tagged occurrences — scoped to this lemma, not the wider سلم root that covers islam/muslim/sallama) first occurs at 4:94: believers on campaign are ordered NOT to say 'you are not a believer' to the man who offers them salam, chasing the goods of this world. Its last occurrence is 97:5: 'Peace it is, until the rising of dawn' — Laylat al-Qadr, a night that does not offer peace but IS peace. Salam enters the mushaf as a greeting a human can refuse and exits as a state nothing can interrupt. First is Medinan (an-Nisa); al-Qadr is Meccan by majority classification (disputed) — mushaf order, not chronology.", "evidence": "lemma سَلام n=42; first=4:94 ('ولا تقولوا لمن القى اليكم السلام لست مومنا تبتغون عرض الحياة الدنيا'), last=97:5 ('سلام هي حتى مطلع الفجر'); tail: 56:26, 56:91, 59:23, 97:5.", "refs": ["4:94", "97:5"], "overlap_note": "none — no published salam article; jannah/vocabulary pieces don't build on 4:94 or the bracket.", "angle": "The Quran's peace-story starts with people too busy fighting to accept a salam, and ends with one night a year when peace stops being an offer and becomes the weather."}, {"id": "BRACKET-10", "lens": "BRACKET", "tier": "high", "verdict": "CONFIRMED", "title_idea": "The Quran's Last 'Orphan' and Its Last 'Denial' Are Next-Door Verses", "claim": "In mushaf order, the root يتم (orphan; 23 tagged segments) first occurs at 2:83 — inside Bani Israil's covenant: worship Allah, honor parents, kin, ORPHANS, the needy — and last occurs at 107:2: 'that is the one who shoves away the orphan.' And the root كذب (to lie/deny; 282 tagged segments) makes its own final appearance one verse earlier, at 107:1: 'have you seen the one who DENIES the Judgment?' The mushaf's last word on orphans and its last word on denial sit in adjacent verses, welded into one definition: lying about religion looks like pushing a child away. First bookend Medinan (al-Baqarah), last Meccan (al-Maʿun) — mushaf order, not chronology.", "evidence": "root يتم n=23; first=2:83, last=107:2; tail: 90:15, 93:6, 93:9, 107:2. root كذب n=282; last=107:1; tail: 96:13, 96:16, 107:1.", "refs": ["2:83", "107:1", "107:2"], "overlap_note": "an-nasr-final-words-corpus-quran is the pattern sibling ('a word retires in a fitting surah') — different surah, different words, and the two-roots-retiring-together mechanic is new.", "angle": "If you want the Quran's closing definition of religious fraud, it isn't a doctrine — it's a doorway with a child being pushed back out of it."}, {"id": "BRACKET-11", "lens": "BRACKET", "tier": "high", "verdict": "CONFIRMED", "title_idea": "The Quran's First 'Forget' Is You Forgetting Yourself. Its Last Is God Promising You Won't.", "claim": "In mushaf order, the root نسي (to forget; 45 tagged segments) first occurs at 2:44 — 'do you command people to righteousness and FORGET yourselves, while you recite the Book?' — and last occurs at 87:6 — 'We will make you recite, so you will not forget.' Both bookends are about forgetting in the presence of recitation: the first is people reciting yet forgetting themselves; the last is God guaranteeing His reciter forgets nothing. First is Medinan (al-Baqarah), last is Meccan (al-Aʿla) — mushaf order, not chronology.", "evidence": "root نسي n=45; first=2:44 (تنسون, 'اتامرون الناس بالبر وتنسون انفسكم وانتم تتلون الكتاب'), last=87:6 (تنسى, 'سنقريك فلا تنسى'); tail: 59:19, 59:19, 87:6.", "refs": ["2:44", "87:6"], "overlap_note": "none — no published nisyan article.", "angle": "Both ends of the Quran's forgetting-story happen mid-recitation — the difference between reading the Book and being carried by it is whether the forgetting stops."}, {"id": "BRACKET-12", "lens": "BRACKET", "tier": "high", "verdict": "CONFIRMED", "title_idea": "God Calls Himself 'The Most Loving' Exactly Twice — Both Times to People Who Least Deserved to Hear It", "claim": "The lemma وَدُود (al-Wadud, 'The Most Loving') occurs exactly twice in the Quran: 11:90, where Shuʿayb tells a town of cheating mockers 'seek your Lord's forgiveness, then turn to Him — my Lord is Rahim, Wadud,' and 85:14 — immediately after the people of the ditch burn believers alive — 'and He is al-Ghafur al-Wadud.' Both occurrences pair the love-name with a mercy/forgiveness name, and both are addressed into the aftermath of grave sin. This doubles as a first/last bracket: the name enters and exits the mushaf only at these two points. Both surahs (Hud, al-Buruj) are Meccan by standard classification.", "evidence": "lemma وَدُود n=2, refs 11:90 ('ان ربي رحيم ودود') and 85:14 ('وهو الغفور الودود'). Wider root ودد n=29 (first 2:96, last 85:14) — the name-lemma scope is what carries the claim.", "refs": ["11:90", "85:14"], "overlap_note": "jamil-seven-beautiful-things is the exactly-N sibling; mahabbah articles cover the حبب root, not ودد. No published Wadud piece.", "angle": "The Quran never says 'The Most Loving' to the already-lovable — both times the name appears, it's being held out to people standing in the wreckage of what they did."}, {"id": "RAREADJ-1", "lens": "RAREADJ", "tier": "high", "verdict": "CONFIRMED", "title_idea": "The Quran Has a Verb for 'Stamping Shut' — and the Only Thing It Ever Stamps Is a Heart", "claim": "The root طبع (to stamp/seal) occurs in exactly 11 verses of the Quran. In all 11, the noun 'heart' (lemma قَلْب) appears in the same verse — zero exceptions, no adjacency window needed. All 11 are Form I verbs with Allah as agent (9 active, 2 passive). The sister root قسو (to harden) shows the same law: 6 verses, heart-noun in the same verse 6/6.", "evidence": "طبع 11/11 same-verse with lemma قَلْب: 4:155, 7:100, 7:101, 9:87, 9:93, 10:74, 16:108, 30:59, 40:35, 47:16, 63:3 (passive: 9:87, 63:3). قسو 6/6: 2:74, 5:13, 6:43, 22:53, 39:22, 57:16. Base rate of qalb-root verses is 2.49%, so 11 straight same-verse hits is a law, not chance.", "refs": ["4:155", "7:100", "9:87", "16:108", "30:59", "47:16", "63:3", "2:74", "39:22"], "overlap_note": "/posts/qalb-sealed-rusted-heart-quran covers the heart's first/last mushaf-order words (khatm/ran framing). This is a different verb (طبع, never covered) and a different claim shape: an exclusivity law — the stamp-verb has no other object in the whole Quran. Must cite the published piece as a sibling and not reuse its first/last framing.", "angle": "You can hear the bureaucratic horror in it: a stamp that closes a file. The Quran owns a verb for that, and in eleven uses it never stamps a door, a book, or a fate — only hearts."}, {"id": "RAREADJ-2", "lens": "RAREADJ", "tier": "high", "verdict": "CONFIRMED", "title_idea": "God Only Ever 'Opens' One Thing", "claim": "The root شرح (to open up/expand) occurs in exactly 5 verses. In all 5, the word 'chest' (root صدر) appears in the same verse — zero exceptions. The Quran never uses this verb for a door, a land, or a matter: only chests. And once (16:106) the chest is opened to disbelief — the verb is an aperture, not a blessing by default.", "evidence": "5/5 same-verse: 6:125 (chest opened to Islam vs made tight), 16:106 (opened a chest to kufr), 20:25 (Musa: 'open my chest'), 39:22 (opened to Islam, contrasted with hardened hearts), 94:1 ('Did We not open your chest?'). Companion root صدر base rate 0.69%.", "refs": ["6:125", "16:106", "20:25", "39:22", "94:1"], "overlap_note": "An IG carousel exists (scripts/carousel/content/sharh-twice.ts, the 20:25/94:1 pairing) but no published article in the 185-list. The article adds the full 5-verse exclusivity law plus the dark twin 16:106, which the carousel does not touch.", "angle": "Musa asked for it, the Prophet was given it without asking — and one verse warns the same door can be opened the other way. Five verses, one verb, one organ."}, {"id": "RAREADJ-3", "lens": "RAREADJ", "tier": "high", "verdict": "CONFIRMED", "title_idea": "The Quran Never Says 'Crushing Distress' Without Saying 'Rescued' in the Same Breath", "claim": "The noun karb (root كرب, crushing distress) occurs in exactly 4 verses — and every one of the 4 also contains the rescue root نجو in the same verse. Zero exceptions, no adjacency window needed. With n=4 this is a complete-set observation, not a statistical law: there is no verse in the Quran where karb appears un-rescued.", "evidence": "4/4 same-verse: 6:64 ('Allah rescues you from it and from every karb'), 21:76 (Nuh: 'We rescued him and his family from the great karb'), 37:76 (Nuh again, same formula), 37:115 (Musa and Harun: 'We rescued them both and their people from the great karb'). Companion root نجو base rate 1.2%.", "refs": ["6:64", "21:76", "37:76", "37:115"], "overlap_note": "none — /posts/qunut-despair-mercy-quran is the template (despair→mercy) but كرب/نجو is an untouched pair; this one is even tighter (100% same-verse, the qunut law needed a next-verse window for 2 of 6).", "angle": "The Quran has a word for the distress that crushes — and grammatically refuses to let it stand alone. Every karb in the Book is already inside a rescue sentence."}, {"id": "RAREADJ-4", "lens": "RAREADJ", "tier": "high", "verdict": "CONFIRMED", "title_idea": "Three People Hid Their Fear in the Quran. All Three Heard the Same Two Words.", "claim": "The verb awjasa (root وجس, to feel a hidden flicker of fear) occurs exactly 3 times, always as 'awjasa khīfah' — the fear root خوف is in the same verse 3/3. And in all 3 scenes the answer is the identical phrase 'la takhaf' (do not fear): same verse in 11:70 and 51:28, the immediately following verse (20:68) for Musa. Complete-set observation (n=3): every concealed fear in the Quran is met, within one verse, by 'do not fear.'", "evidence": "11:70 (Ibrahim and the strange guests — 'qalu la takhaf' same verse), 20:67-68 (Musa before the sorcerers' snakes — 'qulna la takhaf' next verse), 51:28 (Ibrahim again — 'qalu la takhaf' same verse). Root خوف same-verse 3/3; the reassurance speaker is angels twice, Allah once.", "refs": ["11:70", "20:67", "20:68", "51:28"], "overlap_note": "none — no published article on awjasa; the Musa-at-the-bush and Ibrahim-guests narratives exist as story articles but none makes this cross-scene word-law the reveal.", "angle": "It is the Quran's word for the fear you don't say out loud — and the Book never lets it sit for more than one verse before someone says 'don't be afraid.'"}, {"id": "RAREADJ-5", "lens": "RAREADJ", "tier": "high", "verdict": "CONFIRMED", "title_idea": "Four Times the Quran Says 'Hand It Over.' It Only Ever Asks for One Thing.", "claim": "The imperative hātū ('produce it! hand it over!') occurs exactly 4 times in the Quran as a surface word — and all 4 are the identical two-word demand 'hātū burhānakum' (bring your proof). Exact-phrase claim on textSimple: the word هاتوا never appears outside this phrase. Complete-set observation (n=4).", "evidence": "2:111 (against 'only Jews or Christians enter Paradise'), 21:24 (against taking other gods), 27:64 (against a partner besides Allah), 28:75 (on Judgment Day, a witness pulled from every nation — same demand). Surface count of 'هاتوا برهانكم' = 4 = surface count of 'هاتوا'. Root برهن same-verse base rate 0.13%.", "refs": ["2:111", "21:24", "27:64", "28:75"], "overlap_note": "Genre sibling: /posts/aftuni-two-monarchs-counsel-quran and /posts/arini-show-me-ibrahim-musa-quran are imperative-sweep articles — different words, different reveals. No burhan/hatu article exists.", "angle": "Money, worship, loyalty — the Quran never says 'hand it over' about any of them. The only thing it ever demands you produce on the spot is your evidence — three times in debate, and a fourth time on the Day when the demand comes back."}, {"id": "RAREADJ-6", "lens": "RAREADJ", "tier": "high", "verdict": "CONFIRMED", "title_idea": "The Quran's Verb for 'Urging Each Other' Appears 3 Times — Always About Feeding the Poor, Always in the Negative", "claim": "The root حضض (to urge, spur one another on) occurs in exactly 3 verses. All 3 share the same-verse companion 'the food of the poor' (root طعم, 3/3), and all 3 are negated: 'he does not urge…' / 'you do not urge one another…'. Complete-set observation (n=3): the Quran never shows this verb being done — only the failure to do it, and only about one act: feeding the needy.", "evidence": "69:34 ('wa la yahuddu ala ta'am al-miskin' — the man given his book in his left hand), 89:18 ('wa la tahaddun ala ta'am al-miskin' — addressed to a whole society), 107:3 ('wa la yahuddu ala ta'am al-miskin' — the one who denies the Din). Root طعم same-verse 3/3, base rate 0.66%.", "refs": ["69:34", "89:18", "107:3"], "overlap_note": "none — no published article touches hadd/tahaddun or Surah Al-Ma'un's corpus pattern.", "angle": "Of everything a society could fail to campaign for, the Quran indicts exactly one — and it defines the religion-denier not by his creed but by the dinner he never lobbied for."}, {"id": "RAREADJ-7", "lens": "RAREADJ", "tier": "high", "verdict": "CONFIRMED", "title_idea": "The Quran Has a Verb for the Jab That Starts a Fight — and Only One Character Ever Does It", "claim": "The root نزغ (to prod/incite, the needling jab that sets people against each other) occurs in exactly 4 verses — and in all 4 the agent is Shaytan, named in the same verse (root شطن, 4/4, zero exceptions). No human, no jinn, no group ever nazagha in the Quran. Complete-set observation (n=4).", "evidence": "7:200 and 41:36 (near-twin verses: 'if a nazgh from Shaytan prods you, seek refuge'), 17:53 ('Shaytan yanzaghu between them' — right after 'say the better word'), 12:100 (Yusuf, at the reunion: 'after Shaytan nazagha between me and my brothers'). Companion شطن base rate 1.25%.", "refs": ["7:200", "17:53", "41:36", "12:100"], "overlap_note": "Sibling published pieces: /posts/footsteps-of-shaytan (khutuwat — a different exclusive-to-Shaytan word, so do NOT reuse خطو) and /posts/weapons-against-waswasa (waswasa, different verb). The nazgh law itself is unshipped; Yusuf's use of it to excuse his brothers is the emotional payload.", "angle": "When Yusuf finally faced the brothers who threw him in a well, he reached for this verb — the one the Quran reserves for Shaytan alone — and by choosing it, moved the blame off his brothers entirely."}, {"id": "RAREADJ-8", "lens": "RAREADJ", "tier": "high", "verdict": "CONFIRMED", "title_idea": "'Extinguish' Appears 3 Times in the Quran: Twice People Try It on God's Light and Fail, Once God Does It and It Works", "claim": "The root طفأ (to extinguish) occurs in exactly 3 verses — a complete set with a perfect symmetry. Twice the subject is people trying to blow out the light (nur) of Allah 'with their mouths,' and both verses immediately state God will complete His light. Once the subject is Allah, extinguishing the fire (nar) people kindle for war — stated as something He simply does. Scope note: at root level the companion is نور 3/3 same-verse, because nur (light) and nar (fire) share the root ن-و-ر; at lemma level it splits 2 nur / 1 nar — which IS the reveal.", "evidence": "9:32 ('they wish to extinguish the light of Allah with their mouths — Allah refuses except to complete His light'), 61:8 (same structure, 'Allah will complete His light'), 5:64 ('whenever they kindle a fire for war, Allah extinguishes it'). Root نور same-verse 3/3, base rate 2.79%.", "refs": ["9:32", "61:8", "5:64"], "overlap_note": "none — no published article on itfa'/nur; /posts/ibrahim-fire-cool-peaceful is about a different fire and different verb.", "angle": "Same verb, opposite scoreboard: humanity's extinguishing attempts are 0 for 2, God's is 1 for 1 — and the Arabic even rhymes the targets, because 'light' and 'fire' grow from one root."}, {"id": "RAREADJ-9", "lens": "RAREADJ", "tier": "high", "verdict": "CONFIRMED", "title_idea": "The Quran Mentions 'Denying' in 257 Verses and 'Forgiving' in 202 — They Never Once Share a Verse", "claim": "Inverse adjacency law. The root كذب (to lie / to call truth a lie) appears in 257 verses; the root غفر (to forgive) appears in 202 verses. If the two were sprinkled independently you would expect them to land in the same verse about 8 times. Observed: zero — not one verse in the Quran contains both roots. Disclosed window: even loosening to verse±1 within the same surah yields only 9 adjacency cases; at the same-verse level the separation is total.", "evidence": "257 kadhib-root verses x 202 ghafr-root verses / 6236 total = 8.3 expected same-verse co-occurrences; observed 0 (confirmed independently by surface-substring scan: no textSimple verse contains both كذب-family and غفر-family strings). Supporting quarantine: كذب also has zero same-verse co-occurrence with خلق (create, 218 verses, 9.0 expected) and صلح (set right/righteous deeds, 170 verses, 7.0 expected). Verse±1 adjacency cases for kadhib/ghafr: 3:137, 5:10, 5:41, 6:144, 9:90, 16:116, 42:24, 57:19, 59:11.", "refs": ["39:53", "4:48", "5:10", "57:19", "42:24"], "overlap_note": "Structural sibling of /posts/despair-of-mercy-unbelief-quran and the qunut article (both are presence laws; this is the shipped genre's first large-n absence law). Core reveal — a statistically impossible-looking gap between the Quran's forgiveness vocabulary and its denial vocabulary — is unshipped.", "angle": "Forgiveness verses reach thieves, adulterers, even those who fought the Prophet — but the vocabulary of calling truth a lie is kept in a separate room, 6,236 doors and not one shared. The Quran's grammar quietly agrees with its theology: every sin can sit next to forgiveness except the one that denies the Forgiver."}, {"id": "RAREADJ-10", "lens": "RAREADJ", "tier": "high", "verdict": "CONFIRMED", "title_idea": "The Quran's Smallest Unit of Measure Exists Only to Promise You Won't Be Cheated", "claim": "Fatil — the thread in the groove of a date-stone, the Quran's tiniest named quantity — occurs in exactly 3 verses (root فتل). All 3 have the root ظلم (to wrong) in the same verse, zero exceptions, and all 3 are the same negated promise: 'they/you will not be wronged a fatil.' The word never measures anything else — no wealth, no distance, no sin. Complete-set observation (n=3).", "evidence": "4:49 ('wa la yuzlamuna fatila' — on those who certify themselves pure), 4:77 ('wa la tuzlamuna fatila' — to those flinching from the fight: the world is little, the akhirah is better, and you won't be shorted a thread), 17:71 (Judgment Day, books given by the right hand — 'wa la yuzlamuna fatila'). Root ظلم same-verse 3/3, base rate 4.65%.", "refs": ["4:49", "4:77", "17:71"], "overlap_note": "none — no published article on fatil or the Quran's micro-measures.", "angle": "A language invents its smallest unit for what it most fears losing. The Quran coins its tiniest measure for exactly one purpose: to tell you the audit of your life will not short you by the width of a thread."}, {"id": "RAREADJ-11", "lens": "RAREADJ", "tier": "high", "verdict": "CONFIRMED", "title_idea": "Dead by Morning, in Their Own Homes: The 5-Word Formula the Quran Repeats for Every Destroyed Town", "claim": "The word jathimin (root جثم, fallen lifeless where they knelt) occurs in exactly 5 verses — and every one of the 5 carries the same three companions in the same verse: 'seized' (root أخذ, 5/5), 'by morning' (root صبح, 5/5), and 'in their home(s)' (root دور, 5/5). Zero exceptions on all three. The Quran never uses this death-posture word outside the formula: seized, morning, home.", "evidence": "7:78 (Thamud, the quake), 7:91 (Madyan, the quake), 11:67 (Thamud, the blast), 11:94 (Madyan, the blast — same verse first rescues Shu'ayb 'by mercy from Us'), 29:37 (Madyan again). Companion base rates: أخذ 3.91%, صبح 0.69%, دور 0.85% — three simultaneous 5/5 laws.", "refs": ["7:78", "7:91", "11:67", "11:94", "29:37"], "overlap_note": "Narrative articles on Thamud/Shu'ayb exist (/posts/thamud-the-civilization-that-carved-mountains, /posts/the-overturned-cities-...) but none makes the corpus formula the reveal. This is a formula-law piece, not a story piece.", "angle": "The punishment never chases anyone down. Five for five, the Quran's word for the final posture comes with the same stage directions: it happened overnight, and they were found at home — the place they felt safest."}, {"id": "RAREADJ-12", "lens": "RAREADJ", "tier": "high", "verdict": "CONFIRMED", "title_idea": "Every Ear of Grain in the Quran Comes in Sevens", "claim": "The word sunbulah (ear of grain, root سنبل) occurs in exactly 4 verses — and all 4 contain the number seven (root سبع) in the same verse. Zero exceptions. Complete-set observation (n=4): the Quran never mentions an ear of grain without counting to seven, across two unrelated contexts — the charity parable and Yusuf's famine economics.", "evidence": "2:261 (one grain grows seven ears, a hundred grains each — the charity multiplication), 12:43 (the king's dream: seven fat cows, seven green ears), 12:46 (Yusuf asked to interpret: seven and seven again), 12:47 ('you will plant seven years… leave it in its ear'). Root سبع base rate 0.38%.", "refs": ["2:261", "12:43", "12:46", "12:47"], "overlap_note": "none — no published article on sunbulah or Quranic number-word pairings; /posts/jamil-seven-beautiful-things-quran uses seven as a count of results, not as this word-pairing law.", "angle": "One seven multiplies a gift into seven hundred; the other seven rations a nation through famine. The Quran's grain never grows in any other number — abundance and scarcity measured on the same stalk."}];
const POOL_BY_ID = {}; for (const i of POOL) POOL_BY_ID[i.id] = i
const POOL_INDEX = POOL.map(i => `[${i.id}] (${i.lens},${i.verdict}) "${i.title_idea}" — ${i.claim} | REFS ${(i.refs||[]).join(',')} | OVERLAP: ${i.overlap_note}`).join('\n')

const ALREADY_SHIPPED = `ALSO already shipped this week (avoid overlap, NOT in published-articles.md yet): /posts/qatalahum-allah-curse-quran, /posts/orphan-shove-voice-flip-quran, /posts/ibrahim-wife-laugh-strike-quran, /posts/yusuf-decree-worship-none-but-him-quran, /posts/two-who-wronged-themselves-quran, /posts/khawiya-collapsed-roofs-quran.`

const PERSONA_BLOCK = `
FOUR READER PERSONAS (score 1-5; files at ${MEMDIR}/persona_*.md):
- Amina (Reconnector,25-38): born Muslim on her own terms; largest segment; contested-verse search; needs permission + depth w/o Arabic prereqs.
- Khalil (Convert,24-38): intellectual convert; top recommender; needs verifiable citations, ikhtilaf honesty, morphological transparency.
- Sara (Questioning Parent,32-45): teen asks hard questions; WhatsApp sharer; needs something she can SAY, teen-readable.
- Yusuf (Student,18-28): faces academic critique; MSA multiplier; needs citable rigor.`

const ADVISORS = [
  { key:'ZAYNAB', name:'Dr. Zaynab al-Mansouri (Arabic linguistics & classical balaghah)', memfile: MEMDIR+'/advisor_zaynab_al_mansouri.md' },
  { key:'HASAN', name:'Dr. Hasan al-Qasimi (classical tafsir, Al-Azhar + Oxford)', memfile: MEMDIR+'/advisor_hasan_al_qasimi.md' },
  { key:'YASMIN', name:'Dr. Yasmin Farid (academic Quranic studies, U Chicago)', memfile: MEMDIR+'/advisor_yasmin_farid.md' },
  { key:'KHALID', name:'Ustadh Khalid Siddiqui (digital dawah, Muslim youth)', memfile: MEMDIR+'/advisor_khalid_siddiqui.md' },
]

const PROPOSALS_SCHEMA = { type:'object', required:['proposals'], properties:{
  proposals:{type:'array',items:{type:'object',required:['id','title','thesis','exhibits'],properties:{
    id:{type:'string'},title:{type:'string'},thesis:{type:'string'},exhibits:{type:'array',items:{type:'string'}},
    personas:{type:'object'},risks:{type:'string'},why_now:{type:'string'}}}} } }
const CRITIQUE_SCHEMA = { type:'object', required:['critiques'], properties:{
  critiques:{type:'array',items:{type:'object',required:['proposal_id','accuracy','freshness','audience','shippability','notes'],properties:{
    proposal_id:{type:'string'},accuracy:{type:'number'},freshness:{type:'number'},audience:{type:'number'},shippability:{type:'number'},fatal:{type:'boolean'},notes:{type:'string'}}}} } }
const SKEPTIC_SCHEMA = { type:'object', required:['proposal_id','verdict','notes'], properties:{
  proposal_id:{type:'string'},verdict:{type:'string',enum:['SURVIVES','REFUTED']},broken_claims:{type:'array',items:{type:'string'}},required_corrections:{type:'string'},notes:{type:'string'} } }
const DELIB_SCHEMA = { type:'object', required:['recommended','reserve','rationale'], properties:{
  recommended:{type:'array',items:{type:'object',required:['proposal_id','title','why'],properties:{proposal_id:{type:'string'},title:{type:'string'},why:{type:'string'},personas:{type:'object'},corrections_to_apply:{type:'string'}}}},
  reserve:{type:'array',items:{type:'object',required:['proposal_id','title','why'],properties:{proposal_id:{type:'string'},title:{type:'string'},why:{type:'string'}}}},
  rationale:{type:'string'} } }

function advisorPrompt(a) {
  return `You are ${a.name}, standing advisor to AyahGuide (Quranic reflection platform). FIRST read your persona file at ${a.memfile} and inhabit it — your framework, voice, standards. Run ${runDate}.
These 36 insights were mined from the full Quranic corpus and every load-bearing count was mechanically re-verified (35 confirmed, 1 corrected — for the corrected one the claim text below is already the corrected version). Full evidence/refs are in ${LEDGERS}/verified-pool.json if you want depth.
VERIFIED POOL (36):
${POOL_INDEX}
TASK: draft 5-6 article proposals through YOUR lens. May combine insights. Each: { "id":"${a.key}-<n>","title"(layman, simple — no academic vocab),"thesis"(2-3 plain sentences: reveal + why it matters),"exhibits":["<insight ids>"],"personas":{"amina":1-5,"khalil":1-5,"sara":1-5,"yusuf":1-5,"note":"..."},"risks":"...","why_now":"..." }
HARD: Quran-only payoff (no hadith-dependent reveals — policy 2026-07-17); check overlap vs ${REPO}/scripts/braintrust-v2/published-articles.md (185 shipped — read it). ${ALREADY_SHIPPED} scope every claim (root vs lemma vs phrase); first/last=mushaf order; no unprovable superlatives; simple layman prose.
${PERSONA_BLOCK}
OUTPUT: 1) Write proposals JSON to ${LEDGERS}/panel36-propose-${a.key}.json. 2) Return { "proposals":[...] }.`
}
function critiquePrompt(a, othersJson) {
  return `You are ${a.name}, standing advisor to AyahGuide. Read your persona file at ${a.memfile} and inhabit it. CROSS-CRITIQUE: below are proposals from the OTHER three advisors (your slate excluded). Verified pool at ${LEDGERS}/verified-pool.json.
Score EVERY proposal 1-10 through your lens: accuracy (penalize scope-shift, superlatives, hadith-dependence), freshness (read ${REPO}/scripts/braintrust-v2/published-articles.md; ${ALREADY_SHIPPED} penalize near-duplicates), audience (persona pull), shippability (writable this week). "fatal":true only if it must NOT ship as-is (say why). Notes: 1-3 sharp sentences in your voice.
PROPOSALS:
${othersJson}
OUTPUT: 1) Write critiques JSON to ${LEDGERS}/panel36-critique-${a.key}.json. 2) Return { "critiques":[...] }.`
}
function skepticPrompt(p, exhibitsJson) {
  return `You are an adversarial fact-checker with VETO power in AyahGuide's braintrust. BREAK the proposal below; if you can't after genuine effort, it survives. Working dir ${REPO}.
DATA: scripts/.corpus-cache/quranic-corpus.json (dict "S:A"->[segments{loc,word,pos,root,lemma,features}], mushaf order); node_modules/quran-validator/data/quran-verses.json (textSimple for phrase sweeps).
ATTACK with your own python3 (Bash): 1) re-derive EVERY count; 2) scope-shift (root vs lemma vs phrase, silent mixing?); 3) counterexample hunt for always/never/only/exactly-N; 4) first/last by mushaf iteration + hidden-chronology; 5) overlap vs ${REPO}/scripts/braintrust-v2/published-articles.md AND the 6 already-shipped slugs (${ALREADY_SHIPPED}); 6) Quran-only (hadith payoff -> REFUTED); 7) hostile-reader one-tweet rebuttal. Every soft spot -> required_corrections; a load-bearing failure -> REFUTED.
PROPOSAL:
${JSON.stringify(p, null, 1)}
EXHIBITS:
${exhibitsJson}
OUTPUT: 1) Write verdict JSON to ${LEDGERS}/panel36-skeptic-${p.id}.json. 2) Return { "proposal_id","verdict","broken_claims","required_corrections","notes" }.`
}

// ==================== EXECUTION ====================
phase('Propose')
log('Panel over ' + POOL.length + ' verified insights; 4 advisors drafting')
const slates = await parallel(ADVISORS.map(a => () =>
  agent(advisorPrompt(a), { label:'propose:'+a.key, phase:'Propose', schema:PROPOSALS_SCHEMA, effort:'high' })
    .then(r => ({ advisor:a.key, proposals:(r&&r.proposals)||[] }))))
const allProposals = []
for (const s of slates.filter(Boolean)) for (const p of s.proposals) allProposals.push({ ...p, advisor:s.advisor })
log(allProposals.length + ' proposals drafted')

phase('Critique')
const critiques = await parallel(ADVISORS.map(a => () => {
  const others = allProposals.filter(p => p.advisor !== a.key)
  return agent(critiquePrompt(a, JSON.stringify(others,null,1)), { label:'critique:'+a.key, phase:'Critique', schema:CRITIQUE_SCHEMA, effort:'high' })
    .then(r => ({ advisor:a.key, critiques:(r&&r.critiques)||[] })) }))
const scoreMap = {}
for (const c of critiques.filter(Boolean)) for (const cr of c.critiques) {
  if (!scoreMap[cr.proposal_id]) scoreMap[cr.proposal_id] = { total:0,n:0,fatals:0,notes:[] }
  const s = scoreMap[cr.proposal_id]; s.total += (cr.accuracy||0)+(cr.freshness||0)+(cr.audience||0)+(cr.shippability||0); s.n+=1
  if (cr.fatal) s.fatals+=1; s.notes.push(c.advisor+': '+(cr.notes||'')) }
const ranked = allProposals.map(p => ({ p, avg: scoreMap[p.id]?scoreMap[p.id].total/scoreMap[p.id].n:0, fatals: scoreMap[p.id]?scoreMap[p.id].fatals:0, critNotes: scoreMap[p.id]?scoreMap[p.id].notes:[] })).sort((x,y)=>y.avg-x.avg)
const top10 = ranked.filter(r => r.fatals < 2).slice(0,10)
log('Top 10 -> skeptic; ' + ranked.filter(r=>r.fatals>=2).length + ' killed by double-fatal')

phase('Skeptic')
const skeptics = await parallel(top10.map(r => () => {
  const ex = (r.p.exhibits||[]).map(id => POOL_BY_ID[id]).filter(Boolean)
  return agent(skepticPrompt(r.p, JSON.stringify(ex,null,1)), { label:'skeptic:'+r.p.id, phase:'Skeptic', schema:SKEPTIC_SCHEMA, effort:'xhigh' }) }))
const skById = {}; for (const s of skeptics.filter(Boolean)) skById[s.proposal_id] = s
const survivors = top10.filter(r => skById[r.p.id] && skById[r.p.id].verdict === 'SURVIVES')
log(survivors.length + '/' + top10.length + ' survived skeptic')

phase('Deliberate')
const delibInput = survivors.map(r => ({ proposal:r.p, avg_critique_score:Number(r.avg.toFixed(2)), critique_notes:r.critNotes,
  skeptic:{ verdict:'SURVIVES', required_corrections:skById[r.p.id].required_corrections||'', notes:skById[r.p.id].notes||'' } }))
const delib = await agent(`You are the editorial deliberator for AyahGuide (run ${runDate}). Below: proposals that survived verified mining, 4-advisor drafting, cross-critique, and adversarial skeptic veto — drawn from the GRAPH/BRACKET/RAREADJ insight pool (rare-root bridges, first/last mushaf brackets, rare-word adjacency laws). Choose a RECOMMENDED-3 PORTFOLIO (not just top-3 scores — ideally one acquisition/search-doorway piece, one classical-recovery flagship, one high-shareability piece; avoid three of one mechanism), plus a ranked reserve. Score each recommended 1-5 per persona (read ${MEMDIR}/persona_*.md) and place it in the catalog (${REPO}/scripts/braintrust-v2/published-articles.md + the 6 already-shipped: ${ALREADY_SHIPPED}). Fold each skeptic's required_corrections into corrections_to_apply. House rules: Quran-only, simple layman titles, exact scoping, mushaf-order, no superlatives.
SURVIVING PROPOSALS:
${JSON.stringify(delibInput,null,1)}
OUTPUT: 1) Write deliberation JSON to ${LEDGERS}/panel36-deliberation.json. 2) Return { "recommended":[...], "reserve":[...], "rationale":"..." }.`,
  { label:'deliberate', phase:'Deliberate', schema:DELIB_SCHEMA, effort:'high' })

return { runDate, pool_size:POOL.length, proposals:allProposals.length,
  ranked: ranked.map(r => ({ id:r.p.id, title:r.p.title, advisor:r.p.advisor, avg:Number(r.avg.toFixed(2)), fatals:r.fatals })),
  skeptic_verdicts: skeptics.filter(Boolean).map(s => ({ id:s.proposal_id, verdict:s.verdict, notes:s.notes })),
  deliberation: delib }
